<script>
 import ProcessSimulation from './ProcessSimulation.svelte';
 import {onMount} from 'svelte';
 import {getLanguage} from '../i18n.js';
 import {createLabProject} from '../lab-projects.js';
 import {compileLabCode,snippets} from '../lab-code.js';
 let {index}= $props();
 let dialog,terminalInput,opener;let field=$state();let language=$state(getLanguage()),value=$state(''),command=$state(''),error=$state(''),log=$state(''),result=$state(false),file=$state(1);
 const c=$derived(({pt:{title:['Uma página com a sua assinatura.','Um fluxo que faz o trabalho avançar.','Sistemas que finalmente conversam.'],intro:'Um projeto quase pronto. A última peça é sua.',invite:'Vamos construir algo juntos?',start:'Começar experiência',back:'Voltar ao laboratório',files:'EXPLORADOR',guide:'SUA MISSÃO',task:['Dê um nome ao estúdio da página.','Escreva o pedido que vai iniciar o fluxo.','Preencha o nome do novo contato.'],help:'Complete o trecho destacado. Depois digite executar no terminal ou use o botão.',fill:'Preencher comigo',run:'Executar projeto',reset:'Recomeçar',preview:'Prévia',editor:'Editor',safe:'Simulação local · sem instalações · nenhum dado enviado',missing:'Complete o trecho destacado antes de executar.',unknown:'Use executar ou run para abrir a prévia.',done:'Projeto preparado. Abrindo a prévia…',placeholder:['Nome do estúdio','Pedido de exemplo','Nome do contato'],examples:['Forma Studio','Quero um site para meu negócio','Ana Costa'],ready:'Seu projeto está pronto para receber o último detalhe.'},en:{title:['A page with your signature.','A workflow that moves work forward.','Systems that finally connect.'],intro:'An almost finished project. The last piece is yours.',invite:'Shall we build something together?',start:'Start experience',back:'Back to the lab',files:'EXPLORER',guide:'YOUR MISSION',task:['Name the page’s studio.','Write the request that starts the workflow.','Fill in the new contact’s name.'],help:'Complete the highlighted section. Then type run in the terminal or use the button.',fill:'Fill it with me',run:'Run project',reset:'Start over',preview:'Preview',editor:'Editor',safe:'Local simulation · no installation · no data sent',missing:'Complete the highlighted section before running.',unknown:'Use run or executar to open the preview.',done:'Project prepared. Opening preview…',placeholder:['Studio name','Example request','Contact name'],examples:['Forma Studio','I need a website for my business','Anna Costa'],ready:'Your project is ready for the final detail.'},es:{title:['Una página con tu firma.','Un flujo que hace avanzar el trabajo.','Sistemas que por fin se conectan.'],intro:'Un proyecto casi terminado. La última pieza es tuya.',invite:'¿Construimos algo juntos?',start:'Comenzar experiencia',back:'Volver al laboratorio',files:'EXPLORADOR',guide:'TU MISIÓN',task:['Dale un nombre al estudio.','Escribe la solicitud que inicia el flujo.','Completa el nombre del nuevo contacto.'],help:'Completa el fragmento destacado. Después escribe ejecutar en la terminal o usa el botón.',fill:'Completar conmigo',run:'Ejecutar proyecto',reset:'Reiniciar',preview:'Vista previa',editor:'Editor',safe:'Simulación local · sin instalaciones · no se envían datos',missing:'Completa el fragmento destacado antes de ejecutar.',unknown:'Usa ejecutar o run para abrir la vista previa.',done:'Proyecto preparado. Abriendo vista previa…',placeholder:['Nombre del estudio','Solicitud de ejemplo','Nombre del contacto'],examples:['Forma Studio','Necesito un sitio para mi negocio','Ana Costa'],ready:'Tu proyecto está listo para el último detalle.'}})[language]||{});
 const filenames=$derived(['index.html',index===1?'workflow.json':index===2?'contact.json':'hero.html','styles.css']);
 let compiled=$state(''),explanation=$state('');
 const source=$derived(compiled||createLabProject(index,'________',language));
 const taskTitle=$derived((language==='en'?['Write the page heading and link in HTML.','Configure the workflow rule in JSON.','Map the source fields to the CRM.']:language==='es'?['Escribe el título y enlace en HTML.','Configura la regla del flujo en JSON.','Relaciona los campos de origen con el CRM.']:['Escreva o título e o link da página em HTML.','Configure a regra do fluxo em JSON.','Mapeie os campos de origem para o CRM.'])[index]);
 const taskHelp=$derived(language==='en'?'Edit the code directly. Use the example as a guide, then type run in the terminal.':language==='es'?'Edita el código directamente. Usa el ejemplo como guía y escribe ejecutar en la terminal.':'Edite o código diretamente. Use o exemplo como guia e digite executar no terminal.');
 const explanationTitle=$derived(language==='en'?'Do you know what you just did?':language==='es'?'¿Sabes lo que acabas de hacer?':'Sabe o que você fez?');
 const config=$derived(index===0?`{\n  "studio": ${JSON.stringify(value||'________')},\n  "layout": "editorial",\n  "palette": "sage",\n  "responsive": true\n}`:index===1?`{\n  "trigger": "request.received",\n  "request": ${JSON.stringify(value||'________')},\n  "steps": ["organize", "prepare_reply"],\n  "mode": "local-demo"\n}`:`{\n  "source": "website",\n  "name": ${JSON.stringify(value||'________')},\n  "destination": "demo-crm",\n  "stage": "first_conversation"\n}`);
 const code=$derived(file===0?source:file===1?config:source.split('<style>')[1]?.split('</style>')[0]||'');
 function start(){opener=document.activeElement;dialog.showModal();field?.focus();}
 function close(){result=false;dialog.close();opener?.focus();}
 function run(){const output=compileLabCode(index,value,language);if(output.error){error=output.error;result=false;file=1;return;}error='';compiled=output.html;explanation=output.explanation;log=c.done;result=true;}
 function submit(){if(!['run','executar','ejecutar','npm run dev'].includes(command.trim().toLowerCase())){error=c.unknown;return;}command='';run();}
 onMount(()=>{const sync=()=>language=getLanguage();sync();document.addEventListener('languagechange',sync);return()=>document.removeEventListener('languagechange',sync);});
</script>
<section class="lab-invitation"><span class="invitation-index">0{index+1} / loui lab</span><h3>{c.title[index]}</h3><p>{c.intro}</p><div class="invitation-illustration" aria-hidden="true"><span>&lt;/&gt;</span><i></i><b>loui / workspace</b></div><h4>{c.invite}</h4><button class="workbench-start" type="button" onclick={start}>{c.start}<span aria-hidden="true">↗</span></button><p class="workbench-disclaimer">{c.safe}</p></section>
<dialog onkeydown={event=>{if(event.key==='Escape')event.stopPropagation();}} class="lab-workbench" bind:this={dialog} oncancel={event=>{event.preventDefault();close();}}>
 <div class="safari-bar"><button type="button" class="workbench-back" onclick={close} aria-label={c.back}><span aria-hidden="true">←</span> {c.back}</button><div class="address-bar">loui / lab / {['web','automation','integrations'][index]}</div><span class="browser-mark" aria-hidden="true">l /</span></div>
 <div class="ide-titlebar"><span class="ide-project">{['forma-studio','request-flow','connected-workspace'][index]} — loui code</span><span>{c.safe}</span></div>
 <div class="ide-layout">
  <aside class="ide-explorer"><h4>{c.files}</h4><p>⌄ {['forma-studio','request-flow','connected-workspace'][index]}</p>{#each filenames as filename,i}<button type="button" class:chosen={file===i} onclick={()=>file=i}><span class="file-kind">{i===2?'#':i===1?'{}':'<>'}</span>{filename}</button>{/each}<div class="explorer-note">HTML / CSS / JSON<br>loui lab</div></aside>
  <main class="ide-main"><div class="ide-tabs"><button type="button" class:chosen={!result} onclick={()=>result=false}>{filenames[file]}</button><button class:chosen={result} type="button" onclick={()=>{if(value.trim())run();else error=c.missing;}}>{c.preview}</button></div>
   {#if result}<div class="preview-browser"><div><span aria-hidden="true">● ● ●</span><span>preview / {['forma','flow','connect'][index]}</span><button type="button" onclick={()=>result=false}>{c.editor}</button></div><div class="what-you-did" role="status"><strong>{explanationTitle}</strong><p>{explanation}</p></div>{#if index===0}<iframe title={c.preview} sandbox="" srcdoc={source}></iframe>{:else}<ProcessSimulation {index} code={value} {language}/>{/if}</div>
   {:else if file===1}<div class="snippet-editor"><label for={'lab-value-'+index}>{taskTitle}</label><textarea id={'lab-value-'+index} bind:this={field} bind:value spellcheck="false" autocomplete="off" maxlength="800" oninput={()=>{error='';result=false;}} aria-describedby={'snippet-example-'+index}></textarea><p id={'snippet-example-'+index}>{language==='en'?'Example':language==='es'?'Ejemplo':'Exemplo'}</p><pre>{snippets[index]}</pre></div>{:else}<div class="code-pane" role="textbox" aria-readonly="true" aria-multiline="true" tabindex="0" aria-label={filenames[file]}><pre><code>{#each code.split('\n') as line,i}<span class="code-line"><span class="line-number" aria-hidden="true">{i+1}</span><span class:code-tag={line.trim().startsWith('<')} class:code-style={file===2} class:editable-line={file===1&&(line.includes('studio')||line.includes('request')||line.includes('name'))}>{line}</span></span>{/each}</code></pre></div>{/if}
   <section class="ide-terminal"><header>TERMINAL <span>loui / browser</span></header><p class="terminal-ready">{log||c.ready}</p><form onsubmit={event=>{event.preventDefault();submit();}}><label for={'lab-command-'+index}>loui ~ %</label><input id={'lab-command-'+index} bind:this={terminalInput} bind:value={command} autocomplete="off" spellcheck="false" aria-label="Terminal" placeholder={language==='en'?'run':'executar'}/><button type="submit" aria-label={c.run}>↵</button></form><p class="workbench-error" role="status">{error}</p></section>
  </main>
  <aside class="ide-guide"><p class="guide-kicker">{c.guide}</p><span class="step-badge">01 / 02</span><h3>{taskTitle}</h3><p>{taskHelp}</p><button type="button" class="guide-fill" onclick={()=>{value=snippets[index];file=1;error='';result=false;field?.focus();}}>{c.fill}</button><div class="guide-divider"></div><span class="step-badge">02 / 02</span><button type="button" class="guide-run" onclick={run}>{c.run}<span aria-hidden="true">→</span></button><button type="button" class="guide-reset" onclick={()=>{value='';command='';error='';log='';result=false;file=1;compiled='';explanation='';field?.focus();}}>{c.reset}</button></aside>
 </div><div class="ide-statusbar"><span>loui lab</span><span>UTF-8 · {file===2?'CSS':file===1?'JSON':'HTML'} · local</span></div>
</dialog>
